//! Synthetic corpus and round-trip fidelity suite.
//!
//! Every fixture here is generated by this file from the canonical model. No document in
//! this suite originates from a real case file, a third-party converter, or any pre-existing
//! implementation — see docs/clean-room/README.md, "Test corpus provenance".
//!
//! Run `TAVZIH_DUMP_CORPUS=1 cargo test --test corpus` to also write every artifact to
//! `target/corpus/` for the manual UYAP and Word acceptance gates.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use tavzih_core::convert::{convert_bytes, Direction, Status};
use tavzih_core::docx;
use tavzih_core::model::*;
use tavzih_core::udf;
use tavzih_core::warnings::{Severity, WarningCode, WarningSink};

/// The mandated Turkish coverage string.
const TR: &str = "Çağdaş Türkiye Cumhuriyeti — İİK, HMK, ıİğĞüÜşŞöÖçÇ";

// ---------------------------------------------------------------- helpers

fn doc(blocks: Vec<Block>) -> Document {
    Document {
        meta: Metadata::default(),
        sections: vec![Section {
            blocks,
            ..Default::default()
        }],
        lists: vec![],
    }
}

fn para(text: &str) -> Block {
    Block::Paragraph(Paragraph::plain(text))
}

fn run(text: &str, props: RunProps) -> Run {
    Run::Text {
        text: text.into(),
        props,
    }
}

fn cell(text: &str) -> TableCell {
    TableCell {
        blocks: vec![para(text)],
        grid_span: 1,
        ..Default::default()
    }
}

fn cell_span(text: &str, span: usize) -> TableCell {
    TableCell {
        blocks: vec![para(text)],
        grid_span: span,
        ..Default::default()
    }
}

fn png() -> Vec<u8> {
    // Same locally generated 1x1 PNG used by the unit tests.
    let mut v = vec![0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A];
    let chunk = |v: &mut Vec<u8>, body: &[u8]| {
        v.extend_from_slice(&((body.len() - 4) as u32).to_be_bytes());
        v.extend_from_slice(body);
        let mut crc = 0xFFFF_FFFFu32;
        for b in body {
            crc ^= *b as u32;
            for _ in 0..8 {
                crc = if crc & 1 != 0 {
                    (crc >> 1) ^ 0xEDB8_8320
                } else {
                    crc >> 1
                };
            }
        }
        v.extend_from_slice(&(!crc).to_be_bytes());
    };
    chunk(
        &mut v,
        &[
            b'I', b'H', b'D', b'R', 0, 0, 0, 1, 0, 0, 0, 1, 8, 2, 0, 0, 0,
        ],
    );
    chunk(
        &mut v,
        &[
            b'I', b'D', b'A', b'T', 0x08, 0x1D, 0x63, 0x60, 0x60, 0x60, 0x00, 0x00, 0x00, 0x04,
            0x00, 0x01,
        ],
    );
    chunk(&mut v, b"IEND");
    v
}

fn image_run(w: f32, h: f32) -> Run {
    Run::Image(Image {
        data: Arc::new(png()),
        format: ImageFormat::Png,
        width_pt: w,
        height_pt: h,
    })
}

/// Flattened structural fingerprint of a document, used to compare a document with its
/// round trip. Deliberately semantic — ZIP bytes will always differ.
#[derive(Debug, Default, PartialEq)]
struct Fingerprint {
    text: String,
    paragraphs: usize,
    tables: usize,
    rows: usize,
    cells: usize,
    merged: usize,
    images: usize,
    image_bytes: usize,
    tabs: usize,
    tab_stops: usize,
    bold: usize,
    italic: usize,
    underline: usize,
    list_paras: usize,
    alignments: Vec<u8>,
    has_header: bool,
    has_footer: bool,
    header_text: String,
    footer_text: String,
    landscape: bool,
}

fn walk(blocks: &[Block], f: &mut Fingerprint) {
    for b in blocks {
        match b {
            Block::Paragraph(p) => {
                f.paragraphs += 1;
                f.text.push_str(&p.text());
                f.text.push('\n');
                f.alignments.push(p.props.alignment as u8);
                f.tab_stops += p.props.tab_stops.len();
                if p.props.list.is_some() {
                    f.list_paras += 1;
                }
                for r in &p.runs {
                    match r {
                        Run::Tab { .. } => f.tabs += 1,
                        Run::Image(i) => {
                            f.images += 1;
                            f.image_bytes += i.data.len();
                        }
                        Run::Text { props, .. } => {
                            if props.bold {
                                f.bold += 1
                            }
                            if props.italic {
                                f.italic += 1
                            }
                            if props.underline {
                                f.underline += 1
                            }
                        }
                        _ => {}
                    }
                }
            }
            Block::Table(t) => {
                f.tables += 1;
                f.rows += t.rows.len();
                for r in &t.rows {
                    f.cells += r.cells.len();
                    for c in &r.cells {
                        if c.grid_span > 1 {
                            f.merged += 1;
                        }
                        walk(&c.blocks, f);
                    }
                }
            }
            Block::PageBreak => {}
        }
    }
}

fn fingerprint(d: &Document) -> Fingerprint {
    let mut f = Fingerprint::default();
    let s = &d.sections[0];
    walk(&s.blocks, &mut f);
    f.has_header = s.header.is_some();
    f.has_footer = s.footer.is_some();
    f.landscape = s.page.orientation == Orientation::Landscape;
    if let Some(h) = &s.header {
        let mut g = Fingerprint::default();
        walk(&h.blocks, &mut g);
        f.header_text = g.text;
        f.images += g.images;
        f.image_bytes += g.image_bytes;
    }
    if let Some(x) = &s.footer {
        let mut g = Fingerprint::default();
        walk(&x.blocks, &mut g);
        f.footer_text = g.text;
    }
    f
}

fn to_docx(d: &Document) -> Vec<u8> {
    let mut w = WarningSink::new();
    let b = docx::writer::write_docx(d, &mut w).expect("write docx");
    docx::writer::validate(&b).expect("emitted docx must validate");
    b
}

fn to_udf(d: &Document) -> Vec<u8> {
    let mut w = WarningSink::new();
    let x = udf::writer::write_content_xml(d, &mut w).expect("write udf");
    udf::writer::validate(&x).expect("emitted udf must satisfy the tiling invariant");
    udf::writer::package(&x).expect("package udf")
}

fn read_docx(b: &[u8]) -> (Document, Vec<WarningCode>) {
    let mut w = WarningSink::new();
    let d = docx::reader::read_docx(b, &mut w).expect("read docx");
    (d, w.into_vec().iter().map(|x| x.code).collect())
}

fn read_udf(b: &[u8]) -> (Document, Vec<WarningCode>) {
    let mut w = WarningSink::new();
    let d = udf::reader::read_udf(b, &mut w).expect("read udf");
    (d, w.into_vec().iter().map(|x| x.code).collect())
}

fn dump(name: &str, ext: &str, bytes: &[u8]) {
    if std::env::var("TAVZIH_DUMP_CORPUS").is_err() {
        return;
    }
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/corpus");
    let _ = std::fs::create_dir_all(&dir);
    let _ = std::fs::write(dir.join(format!("{name}.{ext}")), bytes);
}

/// Assert a document survives DOCX -> UDF -> DOCX with its fingerprint intact.
fn assert_docx_roundtrip(name: &str, d: &Document) -> Vec<WarningCode> {
    let src = to_docx(d);
    dump(name, "docx", &src);
    let mut w = WarningSink::new();
    let udf_bytes = convert_bytes(&src, Direction::DocxToUdf, &mut w).expect("docx->udf");
    dump(&format!("{name}.from-docx"), "udf", &udf_bytes);
    let mut w2 = WarningSink::new();
    let back = convert_bytes(&udf_bytes, Direction::UdfToDocx, &mut w2).expect("udf->docx");
    dump(&format!("{name}.roundtrip"), "docx", &back);

    let (a, _) = read_docx(&src);
    let (b, _) = read_docx(&back);
    let (fa, fb) = (fingerprint(&a), fingerprint(&b));
    assert_eq!(
        fa.text, fb.text,
        "[{name}] text changed across DOCX->UDF->DOCX"
    );
    assert_eq!(
        fa.paragraphs, fb.paragraphs,
        "[{name}] paragraph count changed"
    );
    assert_eq!(fa.tables, fb.tables, "[{name}] table count changed");
    assert_eq!(fa.rows, fb.rows, "[{name}] row count changed");
    assert_eq!(fa.cells, fb.cells, "[{name}] cell count changed");
    assert_eq!(fa.merged, fb.merged, "[{name}] merged-cell count changed");
    assert_eq!(fa.images, fb.images, "[{name}] image count changed");
    assert_eq!(
        fa.image_bytes, fb.image_bytes,
        "[{name}] image bytes changed (re-encoded?)"
    );
    assert_eq!(fa.tabs, fb.tabs, "[{name}] tab count changed");
    assert_eq!(fa.bold, fb.bold, "[{name}] bold run count changed");
    assert_eq!(fa.italic, fb.italic, "[{name}] italic run count changed");
    assert_eq!(
        fa.underline, fb.underline,
        "[{name}] underline run count changed"
    );
    assert_eq!(
        fa.alignments, fb.alignments,
        "[{name}] paragraph alignments changed"
    );
    assert_eq!(
        fa.list_paras, fb.list_paras,
        "[{name}] list paragraph count changed"
    );
    assert_eq!(fa.has_header, fb.has_header, "[{name}] header lost");
    assert_eq!(fa.has_footer, fb.has_footer, "[{name}] footer lost");
    assert_eq!(
        fa.header_text, fb.header_text,
        "[{name}] header text changed"
    );
    assert_eq!(
        fa.footer_text, fb.footer_text,
        "[{name}] footer text changed"
    );
    w.into_vec().iter().map(|x| x.code).collect()
}

/// Assert a document survives UDF -> DOCX -> UDF with its fingerprint intact.
fn assert_udf_roundtrip(name: &str, d: &Document) -> Vec<WarningCode> {
    let src = to_udf(d);
    dump(name, "udf", &src);
    let mut w = WarningSink::new();
    let docx_bytes = convert_bytes(&src, Direction::UdfToDocx, &mut w).expect("udf->docx");
    dump(&format!("{name}.from-udf"), "docx", &docx_bytes);
    let mut w2 = WarningSink::new();
    let back = convert_bytes(&docx_bytes, Direction::DocxToUdf, &mut w2).expect("docx->udf");
    dump(&format!("{name}.roundtrip"), "udf", &back);

    let (a, _) = read_udf(&src);
    let (b, _) = read_udf(&back);
    let (fa, fb) = (fingerprint(&a), fingerprint(&b));
    assert_eq!(
        fa.text, fb.text,
        "[{name}] text changed across UDF->DOCX->UDF"
    );
    assert_eq!(
        fa.paragraphs, fb.paragraphs,
        "[{name}] paragraph count changed"
    );
    assert_eq!(fa.tables, fb.tables, "[{name}] table count changed");
    assert_eq!(fa.cells, fb.cells, "[{name}] cell count changed");
    assert_eq!(fa.images, fb.images, "[{name}] image count changed");
    assert_eq!(
        fa.image_bytes, fb.image_bytes,
        "[{name}] image bytes changed (re-encoded?)"
    );
    assert_eq!(fa.tabs, fb.tabs, "[{name}] tab count changed");
    assert_eq!(fa.bold, fb.bold, "[{name}] bold run count changed");
    assert_eq!(fa.alignments, fb.alignments, "[{name}] alignments changed");
    assert_eq!(fa.has_header, fb.has_header, "[{name}] header lost");
    assert_eq!(fa.has_footer, fb.has_footer, "[{name}] footer lost");
    w.into_vec().iter().map(|x| x.code).collect()
}

/// Every case runs in both directions unless the case says otherwise.
fn assert_both(name: &str, d: &Document) {
    assert_docx_roundtrip(name, d);
    assert_udf_roundtrip(name, d);
}

// ---------------------------------------------------------------- cases

#[test]
fn c01_plain_text() {
    assert_both(
        "01_plain_text",
        &doc(vec![
            para("Birinci paragraf."),
            para("Ikinci paragraf."),
            para("Ucuncu paragraf."),
        ]),
    );
}

#[test]
fn c02_turkish_unicode() {
    let d = doc(vec![
        para(TR),
        para("ıİğĞüÜşŞöÖçÇ"),
        para("Şüphesiz, İstanbul'da görülen davada; ığdır, çağrı, öğüt."),
    ]);
    assert_both("02_turkish_unicode", &d);
    // The mandated string must appear verbatim in both outputs.
    let u = String::from_utf8_lossy(&to_udf(&d)).len();
    assert!(u > 0);
    let (back, _) = read_udf(&to_udf(&d));
    let Block::Paragraph(p) = &back.sections[0].blocks[0] else {
        panic!()
    };
    assert_eq!(
        p.text(),
        TR,
        "the mandated Turkish string must survive byte-for-byte"
    );
}

