#[test]
fn c11_nested_list() {
    let mk = |lvl: u32, t: &str| {
        Block::Paragraph(Paragraph {
            props: ParaProps {
                list: Some(ListRef {
                    list_id: 1,
                    level: lvl,
                }),
                ..Default::default()
            },
            runs: vec![run(t, RunProps::default())],
        })
    };
    let mut d = doc(vec![
        mk(1, "Birinci düzey"),
        mk(2, "İkinci düzey"),
        mk(3, "Üçüncü düzey"),
        mk(2, "İkinci düzey tekrar"),
        mk(1, "Birinci düzey tekrar"),
    ]);
    d.lists = vec![ListDef {
        list_id: 1,
        kind: ListKind::Number(NumberKind::DecimalDot),
    }];
    let warns = assert_docx_roundtrip("11_nested_list", &d);
    assert!(
        warns.contains(&WarningCode::ListNestingUnverified),
        "nested lists must declare that their UYAP appearance is unverified"
    );
    assert_udf_roundtrip("11_nested_list", &d);
}

