#[test]
fn c17_page_break() {
    // UDF cannot express a page break (EXP-012): the requirement is an explicit warning,
    // not a silent blank line.
    let d = doc(vec![
        para("Birinci sayfa."),
        Block::PageBreak,
        para("İkinci sayfa."),
    ]);
    let warns = assert_docx_roundtrip("17_page_break", &d);
    assert!(
        warns.contains(&WarningCode::PageBreakDropped),
        "a dropped page break must be reported"
    );
    // The text on both sides of the break must survive.
    let src = to_docx(&d);
    let mut w = WarningSink::new();
    let u = convert_bytes(&src, Direction::DocxToUdf, &mut w).unwrap();
    let (back, _) = read_udf(&u);
    let all: String = back.sections[0]
        .blocks
        .iter()
        .filter_map(|b| match b {
            Block::Paragraph(p) => Some(p.text()),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("|");
    assert!(all.contains("Birinci sayfa.") && all.contains("İkinci sayfa."));
}

