#[test]
fn c22_long_legal_document() {
    // A realistic pleading: headings, a numbered argument list, tabs, a table, a footer.
    let stops = vec![
        TabStop {
            pos_pt: 85.0,
            align: TabAlign::Left,
        },
        TabStop {
            pos_pt: 100.0,
            align: TabAlign::Left,
        },
    ];
    let mut blocks: Vec<Block> = vec![
        Block::Paragraph(Paragraph {
            props: ParaProps {
                alignment: Alignment::Center,
                ..Default::default()
            },
            runs: vec![run(
                "İSTANBUL ANADOLU 7. ASLİYE HUKUK MAHKEMESİ'NE",
                RunProps {
                    bold: true,
                    font_size_pt: Some(14.0),
                    ..Default::default()
                },
            )],
        }),
        Block::Paragraph(Paragraph {
            props: ParaProps {
                tab_stops: stops.clone(),
                ..Default::default()
            },
            runs: vec![run("DAVACI\t:\tAli VELİ", RunProps::default())],
        }),
        Block::Paragraph(Paragraph {
            props: ParaProps {
                tab_stops: stops.clone(),
                ..Default::default()
            },
            runs: vec![run("VEKİLİ\t:\tAv. Ayşe FATMA", RunProps::default())],
        }),
        Block::Paragraph(Paragraph {
            props: ParaProps {
                tab_stops: stops.clone(),
                ..Default::default()
            },
            runs: vec![run("KONU\t:\tAlacak davası", RunProps::default())],
        }),
        Block::Paragraph(Paragraph {
            props: ParaProps {
                alignment: Alignment::Left,
                ..Default::default()
            },
            runs: vec![run(
                "AÇIKLAMALAR",
                RunProps {
                    bold: true,
                    underline: true,
                    ..Default::default()
                },
            )],
        }),
    ];
    for i in 1..=120 {
        blocks.push(Block::Paragraph(Paragraph {
            props: ParaProps {
                alignment: Alignment::Justify,
                line_spacing_extra: 0.5,
                first_line_indent_pt: 21.0,
                list: Some(ListRef { list_id: 1, level: 1 }),
                ..Default::default()
            },
            runs: vec![
                run(&format!("{i}. "), RunProps { bold: true, ..Default::default() }),
                run(&format!("Müvekkil ile davalı arasındaki hukuki ilişki {i}. kez ele alınmıştır. {TR}"), RunProps::default()),
            ],
        }));
    }
    blocks.push(Block::Table(Table {
        column_widths: vec![60.0, 240.0, 120.0],
        border: TableBorder::Cell,
        rows: (0..12)
            .map(|i| TableRow {
                cells: vec![
                    cell(&format!("{}", i + 1)),
                    cell(&format!("Kalem {}", i + 1)),
                    cell("1.000,00 TL"),
                ],
                is_header: i == 0,
                ..Default::default()
            })
            .collect(),
        ..Default::default()
    }));
    let mut d = doc(blocks);
    d.lists = vec![ListDef {
        list_id: 1,
        kind: ListKind::Number(NumberKind::DecimalDot),
    }];
    d.sections[0].footer = Some(HeaderFooter {
        blocks: vec![para("Av. Ayşe FATMA")],
        ..Default::default()
    });
    assert_both("22_long_legal_document", &d);
}

#[test]
fn c23_output_name_collision() {
    use tavzih_core::convert::{convert_file_to, unique_output_path_in};
    let dir = std::env::temp_dir().join("tavzih-corpus-collision");
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let out = dir.join("cikti");
    let src = dir.join("Dilekçe.docx");
    std::fs::write(&src, to_docx(&doc(vec![para("x")]))).unwrap();

    let mut produced = Vec::new();
    for _ in 0..3 {
        let r = convert_file_to(&src, &out);
        assert_eq!(r.status, Status::Success, "{:?}", r.error);
        assert!(r.source_unchanged);
        produced.push(PathBuf::from(r.output.unwrap()));
    }
    let names: Vec<String> = produced
        .iter()
        .map(|p| p.file_name().unwrap().to_string_lossy().to_string())
        .collect();
    assert_eq!(
        names,
        vec!["Dilekçe.udf", "Dilekçe (2).udf", "Dilekçe (3).udf"]
    );
    // Every one still exists: nothing was overwritten.
    for p in &produced {
        assert!(p.exists());
    }
    assert!(
        unique_output_path_in(&out, &src, "udf")
            .unwrap()
            .file_name()
            .unwrap()
            == "Dilekçe (4).udf"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn c24_corrupt_docx() {
    use tavzih_core::ErrorCode;
    let mut w = WarningSink::new();
    // Not a ZIP at all.
    let e = docx::reader::read_docx(b"bu bir docx degil", &mut w).unwrap_err();
    assert_eq!(e.code, ErrorCode::InvalidDocx);
    // A ZIP that is not a WordprocessingML package.
    let mut cur = std::io::Cursor::new(Vec::new());
    {
        use std::io::Write;
        let mut z = zip::ZipWriter::new(&mut cur);
        let o: zip::write::FileOptions<'_, ()> = zip::write::FileOptions::default();
        z.start_file("hello.txt", o).unwrap();
        z.write_all(b"hi").unwrap();
        z.finish().unwrap();
    }
    let bytes = cur.into_inner();
    dump("24_corrupt_docx", "docx", &bytes);
    let e = docx::reader::read_docx(&bytes, &mut w).unwrap_err();
    assert_eq!(e.code, ErrorCode::InvalidDocx);
    // Truncated ZIP.
    let good = to_docx(&doc(vec![para("x")]));
    let e = docx::reader::read_docx(&good[..good.len() / 2], &mut w).unwrap_err();
    assert_eq!(e.code, ErrorCode::InvalidDocx);
}

#[test]
fn c25_corrupt_udf() {
    use tavzih_core::ErrorCode;
    let mut w = WarningSink::new();
    let e = udf::reader::read_udf(b"bu bir udf degil", &mut w).unwrap_err();
    assert_eq!(e.code, ErrorCode::InvalidUdf);

    // A ZIP with no content.xml.
    let mut cur = std::io::Cursor::new(Vec::new());
    {
        use std::io::Write;
        let mut z = zip::ZipWriter::new(&mut cur);
        let o: zip::write::FileOptions<'_, ()> = zip::write::FileOptions::default();
        z.start_file("sign.sgn", o).unwrap();
        z.write_all(b"only a signature").unwrap();
        z.finish().unwrap();
    }
    let bytes = cur.into_inner();
    dump("25_corrupt_udf", "udf", &bytes);
    assert_eq!(
        udf::reader::read_udf(&bytes, &mut w).unwrap_err().code,
        ErrorCode::InvalidUdf
    );

    // content.xml that is not well-formed enough to carry a buffer.
    let mut cur = std::io::Cursor::new(Vec::new());
    {
        use std::io::Write;
        let mut z = zip::ZipWriter::new(&mut cur);
        let o: zip::write::FileOptions<'_, ()> = zip::write::FileOptions::default();
        z.start_file("content.xml", o).unwrap();
        z.write_all(b"<?xml version=\"1.0\"?><template format_id=\"1.8\"></template>")
            .unwrap();
        z.finish().unwrap();
    }
    assert_eq!(
        udf::reader::read_udf(&cur.into_inner(), &mut w)
            .unwrap_err()
            .code,
        ErrorCode::InvalidUdf
    );
}

