#[test]
fn c26_hostile_archives_are_refused() {
    use tavzih_core::ErrorCode;
    let mut w = WarningSink::new();

    // XXE / entity expansion vector.
    let mut cur = std::io::Cursor::new(Vec::new());
    {
        use std::io::Write;
        let mut z = zip::ZipWriter::new(&mut cur);
        let o: zip::write::FileOptions<'_, ()> = zip::write::FileOptions::default();
        z.start_file("content.xml", o).unwrap();
        z.write_all(
            b"<?xml version=\"1.0\"?><!DOCTYPE t [<!ENTITY a \"AAAA\">]><template format_id=\"1.8\">\
              <content><![CDATA[&a;]]></content><elements/></template>",
        )
        .unwrap();
        z.finish().unwrap();
    }
    let e = udf::reader::read_udf(&cur.into_inner(), &mut w).unwrap_err();
    assert_eq!(
        e.code,
        ErrorCode::UnsafeArchive,
        "a DOCTYPE must be refused"
    );

    // Zip Slip entry name.
    let mut cur = std::io::Cursor::new(Vec::new());
    {
        use std::io::Write;
        let mut z = zip::ZipWriter::new(&mut cur);
        let o: zip::write::FileOptions<'_, ()> = zip::write::FileOptions::default();
        z.start_file("../../../../etc/passwd", o).unwrap();
        z.write_all(b"pwned").unwrap();
        z.start_file("content.xml", o).unwrap();
        z.write_all(b"<template/>").unwrap();
        z.finish().unwrap();
    }
    let e = udf::reader::read_udf(&cur.into_inner(), &mut w).unwrap_err();
    assert_eq!(
        e.code,
        ErrorCode::UnsafeArchive,
        "path traversal must be refused"
    );
}

