/// P1 REGRESSION — Word refused a converted pleading with "Text Recovery".
///
/// UYAP writes the editor's full default ruler: real documents carry 455 tab stops running
/// out to 223 inches, of which only a dozen fall inside the page. Passing them through
/// produced 16,217 `<w:tab>` elements with positions to 321,732 twips, and Word rejected the
/// whole document. Well-formed XML with resolvable relationships is not the same thing as a
/// file Word will open.
#[test]
fn c51_absurd_tab_stops_are_bounded_to_what_word_accepts() {
    // The shape observed in the failing document.
    let stops: Vec<TabStop> = (1..=455)
        .map(|i| TabStop {
            pos_pt: i as f32 * 35.43307,
            align: TabAlign::Left,
        })
        .collect();
    let d = doc((0..90)
        .map(|i| {
            Block::Paragraph(Paragraph {
                props: ParaProps {
                    tab_stops: stops.clone(),
                    ..Default::default()
                },
                runs: vec![run(&format!("Paragraf {i}\tdeğer"), RunProps::default())],
            })
        })
        .collect());

    // to_docx() validates, and validation now enforces Word's limits.
    let bytes = to_docx(&d);
    let body = part_text(&bytes, "word/document.xml");

    let per_para: Vec<usize> = body
        .split("<w:tabs>")
        .skip(1)
        .map(|b| {
            b[..b.find("</w:tabs>").unwrap_or(b.len())]
                .matches("<w:tab ")
                .count()
        })
        .collect();
    assert!(
        per_para.iter().all(|n| *n <= 64),
        "a paragraph kept {} tab stops; Word accepts at most 64",
        per_para.iter().max().unwrap()
    );

    let positions: Vec<i64> = body
        .match_indices("w:pos=\"")
        .filter_map(|(i, _)| {
            let a = &body[i + 7..];
            a[..a.find('"')?].parse().ok()
        })
        .collect();
    assert!(!positions.is_empty(), "all tab stops were dropped");
    assert!(
        positions.iter().all(|p| *p <= 31_680),
        "a tab position of {} twips is outside Word's range",
        positions.iter().max().unwrap()
    );
    // Only stops inside the text column survive, so the part stays a sane size.
    assert!(
        body.len() < 200_000,
        "document.xml is {} bytes; the ruler was not bounded",
        body.len()
    );
}

/// Stops that the reader could actually have reached are a real loss and must be reported;
/// unreachable ones are not.
#[test]
fn c52_only_losing_reachable_tab_stops_is_reported() {
    // 500 stops packed inside the text column: more than Word accepts, so some real ones go.
    let packed: Vec<TabStop> = (1..=500)
        .map(|i| TabStop {
            pos_pt: i as f32 * 0.8,
            align: TabAlign::Left,
        })
        .collect();
    let mut w = WarningSink::new();
    let d = doc(vec![Block::Paragraph(Paragraph {
        props: ParaProps {
            tab_stops: packed,
            ..Default::default()
        },
        runs: vec![run("x", RunProps::default())],
    })]);
    docx::writer::write_docx(&d, &mut w).unwrap();
    assert!(
        w.has(WarningCode::TabStopsTrimmed),
        "dropping reachable tab stops must be reported"
    );

    // The unreachable ruler, by contrast, costs the reader nothing and must stay quiet.
    let ruler: Vec<TabStop> = (1..=455)
        .map(|i| TabStop {
            pos_pt: i as f32 * 35.43307,
            align: TabAlign::Left,
        })
        .collect();
    let mut w2 = WarningSink::new();
    let d2 = doc(vec![Block::Paragraph(Paragraph {
        props: ParaProps {
            tab_stops: ruler,
            ..Default::default()
        },
        runs: vec![run("x", RunProps::default())],
    })]);
    docx::writer::write_docx(&d2, &mut w2).unwrap();
    assert!(
        !w2.has(WarningCode::TabStopsTrimmed),
        "stops beyond the page are unreachable; dropping them is not a fidelity loss"
    );
}

/// The validator must refuse a package Word would reject, so this can never again be
/// reported as a successful conversion.
#[test]
fn c53_validator_refuses_a_package_that_exceeds_word_limits() {
    let good = to_docx(&doc(vec![Block::Paragraph(Paragraph {
        props: ParaProps {
            tab_stops: vec![TabStop {
                pos_pt: 100.0,
                align: TabAlign::Left,
            }],
            ..Default::default()
        },
        runs: vec![run("x", RunProps::default())],
    })]));

    // Re-inject the failure shape: an out-of-range tab position.
    let broken = rewrite_part(&good, "word/document.xml", |xml| {
        xml.replace("w:pos=\"2000\"", "w:pos=\"321732\"")
    });
    let e = docx::writer::validate(&broken).unwrap_err();
    assert_eq!(e.code, tavzih_core::ErrorCode::OutputValidationFailed);
    assert!(e.detail.contains("321732"), "{}", e.detail);

    // And too many stops in one paragraph.
    let many = (0..80)
        .map(|i| format!("<w:tab w:val=\"left\" w:pos=\"{}\"/>", 100 + i * 10))
        .collect::<String>();
    let broken2 = rewrite_part(&good, "word/document.xml", |xml| {
        let i = xml.find("<w:tabs>").unwrap() + "<w:tabs>".len();
        let j = xml.find("</w:tabs>").unwrap();
        format!("{}{many}{}", &xml[..i], &xml[j..])
    });
    let e2 = docx::writer::validate(&broken2).unwrap_err();
    assert_eq!(e2.code, tavzih_core::ErrorCode::OutputValidationFailed);
    assert!(e2.detail.contains("tab stops"), "{}", e2.detail);
}

/// Paragraph properties must be emitted in CT_PPr schema order.
#[test]
fn c54_paragraph_properties_are_in_schema_order() {
    let d = doc(vec![Block::Paragraph(Paragraph {
        props: ParaProps {
            alignment: Alignment::Justify,
            left_indent_pt: 36.0,
            hanging_pt: 18.0,
            space_before_pt: 6.0,
            line_spacing_extra: 0.5,
            tab_stops: vec![TabStop {
                pos_pt: 100.0,
                align: TabAlign::Left,
            }],
            list: Some(ListRef {
                list_id: 1,
                level: 1,
            }),
            ..Default::default()
        },
        runs: vec![run("x", RunProps::default())],
    })]);
    let mut dd = d.clone();
    dd.lists = vec![ListDef {
        list_id: 1,
        kind: ListKind::Number(NumberKind::DecimalDot),
    }];
    let body = part_text(&to_docx(&dd), "word/document.xml");
    let ppr = &body[body.find("<w:pPr>").unwrap()..body.find("</w:pPr>").unwrap()];
    const ORDER: [&str; 5] = ["<w:numPr>", "<w:tabs>", "<w:spacing", "<w:ind", "<w:jc"];
    let mut last = 0usize;
    for tag in ORDER {
        let at = ppr
            .find(tag)
            .unwrap_or_else(|| panic!("{tag} missing from {ppr}"));
        assert!(at >= last, "{tag} is out of CT_PPr order in {ppr}");
        last = at;
    }
}

/// Rebuild a package with one part replaced.
fn rewrite_part(docx: &[u8], part: &str, f: impl Fn(&str) -> String) -> Vec<u8> {
    use std::io::{Read, Write};
    let mut z = zip::ZipArchive::new(std::io::Cursor::new(docx)).unwrap();
    let mut cur = std::io::Cursor::new(Vec::new());
    {
        let mut zw = zip::ZipWriter::new(&mut cur);
        let o: zip::write::FileOptions<'_, ()> = zip::write::FileOptions::default();
        for i in 0..z.len() {
            let mut e = z.by_index(i).unwrap();
            let name = e.name().to_string();
            let mut v = Vec::new();
            e.read_to_end(&mut v).unwrap();
            if name == part {
                v = f(&String::from_utf8_lossy(&v)).into_bytes();
            }
            zw.start_file(name, o).unwrap();
            zw.write_all(&v).unwrap();
        }
        zw.finish().unwrap();
    }
    cur.into_inner()
}

// ================================================== conversion-warning cancellation

/// Cancelling the pre-conversion warning must leave nothing behind.
///
/// The dialog lives in the window, so what is asserted here is the invariant it relies on:
/// a job that is never started writes no output and does not touch the source. If cancelling
/// ever did start a job, this is the property that would break.
#[test]
fn c55_a_job_that_is_never_started_writes_nothing_and_touches_nothing() {
    let d = batch_dir("cancelled");
    let out = d.join("cikti");
    let srcs = vec![
        write_docx_file(&d, "Dilekçe.docx"),
        write_udf_file(&d, "Karar.udf"),
    ];
    let before: Vec<String> = srcs
        .iter()
        .map(|p| tavzih_core::convert::sha256_file(p).unwrap())
        .collect();

    // The user pressed Vazgeç: convert_batch_to is simply never called.
    assert!(
        !out.exists(),
        "cancelling must not create the output directory"
    );
    assert_sources_untouched(&srcs, &before);

    // Confirming afterwards still works and is unaffected by the earlier cancellation.
    let r = tavzih_core::convert::convert_batch_to(&srcs, &out, Some("2026-08-30_2300"));
    assert_eq!(r.failed, 0);
    assert!(r.all_sources_unchanged);
    assert_sources_untouched(&srcs, &before);
    let _ = std::fs::remove_dir_all(&d);
}

/// The output root must resolve on either platform, from the right environment variable.
#[test]
fn c56_output_root_is_platform_correct() {
    let r = tavzih_core::convert::output_root();
    let tail: Vec<String> = r
        .components()
        .rev()
        .take(3)
        .map(|c| c.as_os_str().to_string_lossy().to_string())
        .collect();
    assert_eq!(tail, vec!["Dönüştürülen Belgeler", "Tavzih", "Documents"]);
    assert!(r.is_absolute() || cfg!(test), "{}", r.display());
}

/// Output naming must survive names that are awkward on Windows: Turkish characters,
/// spaces, dots and length.
#[test]
fn c57_awkward_file_names_produce_usable_outputs() {
    let d = batch_dir("names");
    let out = d.join("cikti");
    let long_name = "çok uzun bir dosya adı ".repeat(6) + "son.docx";
    let names = [
        "İstinaf Başvuru Dilekçesi ve Ekleri.docx",
        "Şirket - Ödeme Emri (2026-428) v2.1.docx",
        long_name.as_str(),
    ];
    let mut srcs = Vec::new();
    for n in &names {
        let p = d.join(n.trim());
        std::fs::write(&p, to_docx(&doc(vec![para("içerik")]))).unwrap();
        srcs.push(p);
    }
    let before: Vec<String> = srcs
        .iter()
        .map(|p| tavzih_core::convert::sha256_file(p).unwrap())
        .collect();

    let r = tavzih_core::convert::convert_batch_to(&srcs, &out, Some("2026-08-30_2300"));
    assert_eq!(
        r.failed,
        0,
        "{:?}",
        r.items.iter().map(|i| &i.error).collect::<Vec<_>>()
    );
    let entries = zip_entries(&PathBuf::from(r.output.unwrap()));
    assert_eq!(entries.len(), 3, "{entries:?}");
    assert!(entries.iter().any(|e| e.contains("İstinaf")), "{entries:?}");
    assert!(entries.iter().any(|e| e.contains("Ödeme")), "{entries:?}");
    // No entry may carry a separator that would create an unintended folder.
    for e in &entries {
        assert_eq!(e.matches('/').count(), 1, "unexpected nesting in {e}");
        assert!(!e.contains('\\'), "backslash in ZIP entry {e}");
    }
    assert_sources_untouched(&srcs, &before);
    let _ = std::fs::remove_dir_all(&d);
}

// ---------------------------------------------------------------- hardening: field-code leak (skeptic 3, P1)

/// Ham bir DOCX paketi kur: yalnızca `word/document.xml`. Okuyucu bu tek parçayı
/// zorunlu tutar, gerisi opsiyoneldir (reader.rs `load_package`).
fn raw_docx(document_xml: &str) -> Vec<u8> {
    use std::io::Write;
    let mut cur = std::io::Cursor::new(Vec::new());
    {
        let mut z = zip::ZipWriter::new(&mut cur);
        let o: zip::write::FileOptions<'_, ()> = zip::write::FileOptions::default();
        z.start_file("word/document.xml", o).unwrap();
        z.write_all(document_xml.as_bytes()).unwrap();
        z.finish().unwrap();
    }
    cur.into_inner()
}

fn doc_all_text(d: &Document) -> String {
    fn blocks(out: &mut String, bs: &[Block]) {
        for b in bs {
            match b {
                Block::Paragraph(p) => {
                    out.push_str(&p.text());
                    out.push('\n');
                }
                Block::Table(t) => {
                    for r in &t.rows {
                        for c in &r.cells {
                            blocks(out, &c.blocks);
                        }
                    }
                }
                _ => {}
            }
        }
    }
    let mut s = String::new();
    for sec in &d.sections {
        blocks(&mut s, &sec.blocks);
    }
    s
}

/// P1 (skeptic 3): Word'ün "complex field" yapısı `fldChar(begin) → instrText(KOD)
/// → fldChar(separate) → önbelleğe alınmış görünen değer → fldChar(end)` biçimindedir.
/// `instrText` içindeki alan kodu (HYPERLINK hedefi, REF/PAGEREF yer imi, MERGEFIELD
/// veri adı) KULLANICIYA GÖSTERİLMEZ; yalnızca separate'ten sonraki değer gösterilir.
/// Okuyucu instrText metnini bastırmazsa alan kodu gövde metnine sızar — kullanıcı
/// belgesine ait olmayan, hatta gizli olabilecek (iç URL, yer imi) veri Dönüştür
/// çıktısında görünür.
#[test]
fn hardening_complex_field_instruction_codes_never_leak_into_body() {
    let xml = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:r><w:t xml:space="preserve">Görülen: </w:t></w:r>
      <w:r><w:fldChar w:fldCharType="begin"/></w:r>
      <w:r><w:instrText xml:space="preserve"> HYPERLINK "http://ic-sunucu.example/kayit?dava=2026-42&amp;gizli=1" </w:instrText></w:r>
      <w:r><w:fldChar w:fldCharType="separate"/></w:r>
      <w:r><w:t>Ek-3 numaralı belge</w:t></w:r>
      <w:r><w:fldChar w:fldCharType="end"/></w:r>
    </w:p>
    <w:p>
      <w:r><w:t xml:space="preserve">Bakınız </w:t></w:r>
      <w:r><w:fldChar w:fldCharType="begin"/></w:r>
      <w:r><w:instrText xml:space="preserve"> REF _Ref123456 \h </w:instrText></w:r>
      <w:r><w:fldChar w:fldCharType="separate"/></w:r>
      <w:r><w:t>madde 5</w:t></w:r>
      <w:r><w:fldChar w:fldCharType="end"/></w:r>
      <w:r><w:t>.</w:t></w:r>
    </w:p>
    <w:p>
      <w:r><w:fldChar w:fldCharType="begin"/></w:r>
      <w:r><w:instrText xml:space="preserve"> MERGEFIELD MusteriTCKN </w:instrText></w:r>
      <w:r><w:fldChar w:fldCharType="end"/></w:r>
    </w:p>
  </w:body>
</w:document>"#;
    let (d, warns) = read_docx(&raw_docx(xml));
    let text = doc_all_text(&d);

    // Görünen değerler korunur.
    assert!(text.contains("Görülen: Ek-3 numaralı belge"), "görünen değer kayıp: {text:?}");
    assert!(text.contains("Bakınız madde 5."), "REF görünen değeri kayıp: {text:?}");

    // Alan kodunun HİÇBİR parçası gövdeye sızmamalı.
    for needle in [
        "HYPERLINK",
        "ic-sunucu.example",
        "gizli=1",
        "REF _Ref123456",
        "_Ref123456",
        "MERGEFIELD",
        "MusteriTCKN",
        "\\h",
    ] {
        assert!(
            !text.contains(needle),
            "alan kodu gövde metnine sızdı: {needle:?} in {text:?}"
        );
    }

    // Kayıp sessiz olmamalı: kullanıcı alanların düzleştirildiğini görmeli.
    assert!(
        warns.contains(&WarningCode::FieldFlattened),
        "alan düzleştirme uyarısı verilmedi: {warns:?}"
    );
}
